from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent
old=json.loads((R/'inventory_before.json').read_text(encoding='utf-8-sig'))
r=json.loads((R/'recovery_restored_001.json').read_text(encoding='utf-8-sig'))
receipt=json.loads((R/'apply_materials_stage3_001.json').read_text(encoding='utf-8-sig'))
a={c['name']:c for c in old['components']};b={c['name']:c for c in r['components_after_restore']}
changes=[]
for n,x in a.items():
 y=b.get(n)
 if y and ((x['suppression']==0)!=(y['suppression']==0) or x['hidden']!=y['hidden'] or x['configuration']!=y['configuration']):changes.append(n)
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
checks={n:sha(p['path'])==p['disk_sha256_after'] for n,p in receipt['parts'].items()}
assert not(set(a)-set(b)) and not(set(b)-set(a)) and not changes
assert all(v.get('material_matches') for v in r['persisted_material_checks'].values()) and len(r['persisted_material_checks'])==14
assert all(checks.values()) and r['working_checkpoint_saved'] and r['checkpoint_save_errors']==0
